import{toErrorMessage}from"#shared/errors.js";const activeSandboxConnections=new Map;function createKey(e){return`${e.providerName}\0${e.sessionId}`}function trackActiveSandboxConnection(e){activeSandboxConnections.set(createKey(e),e.connection)}function untrackActiveSandboxConnection(e){let t=createKey(e);(e.connection===void 0||activeSandboxConnections.get(t)===e.connection)&&activeSandboxConnections.delete(t)}async function shutdownActiveSandboxConnections(e){let t=[...activeSandboxConnections.entries()];activeSandboxConnections.clear();let n=await Promise.allSettled(t.map(([,e])=>e.stop()));for(let[r,i]of n.entries())if(i.status===`rejected`){let n=t[r];e?.log?.(`failed to shut down sandbox "${n?.[0]??`unknown`}": ${toErrorMessage(i.reason)}`)}}export{shutdownActiveSandboxConnections,trackActiveSandboxConnection,untrackActiveSandboxConnection};